{{- $trace := .Values.traceContextEnabled }}
{{- if or .Values.traceContextWriteEnabled .Values.traceContextWriteEverEnabled .Values.langfuseEnabled }}
{{- if not $trace }}{{ fail "Enable the compatible Trace reader before writing or Langfuse" }}{{ end }}
{{- end }}
{{- if and .Values.traceContextWriteEnabled (not .Values.traceContextWriteEverEnabled) }}{{ fail "Record the irreversible reader compatibility floor before writing" }}{{ end }}
{{- if $trace }}
{{- if not (and .Values.workloads.api .Values.workloads.runner (has "api" .Values.apmWorkloads) (has "runner" .Values.apmWorkloads)) }}{{ fail "Both instrumented API and runner readers are required" }}{{ end }}
{{- end }}
{{- $obs := .Files.Get "files/observability.json" | fromJson }}
{{- $active := or .Values.workloads.api .Values.workloads.runner }}
{{- if $active }}
{{- if not (and .Values.accessEnabled .Values.review.sourceCompatible .Values.review.imageReviewed .Values.review.connectionsReviewed) }}{{ fail "Review compatible source, immutable image, Secret supply and shared model access before enabling AI" }}{{ end }}
{{- if not (regexMatch "^ghcr.io/100-hours-a-week/yeodam-ai-app@sha256:[a-f0-9]{64}$" .Values.image) }}{{ fail "Immutable AI app image required" }}{{ end }}
{{- if not (and (regexMatch "^[a-f0-9]{40}$" .Values.source) (regexMatch "^[a-f0-9]{64}$" .Values.configurationRevision)) }}{{ fail "Source and metadata revision required" }}{{ end }}
{{- end }}
{{- if .Values.accessEnabled }}
{{- range $key, $ca := .Values.trust }}{{ if not (contains "-----BEGIN CERTIFICATE-----" $ca) }}{{ fail "Public Redis/Qdrant/Kafka CA required" }}{{ end }}{{ end }}
{{- $c := .Files.Get "files/contract.json" | fromJson }}
---
apiVersion: v1
kind: ConfigMap
metadata: {name: ai-trust, namespace: ai}
data:
  redis.crt: {{ .Values.trust.redis | quote }}
  qdrant.crt: {{ .Values.trust.qdrant | quote }}
  kafka.crt: {{ .Values.trust.kafka | quote }}
---
apiVersion: v1
kind: ConfigMap
metadata: {name: ai-runtime-scripts, namespace: ai}
data:
{{ (.Files.Glob "files/runtime/*").AsConfig | indent 2 }}
{{- if .Values.apmWorkloads }}
  sitecustomize.py: |
{{ .Files.Get "files/apm/sitecustomize.py" | indent 4 }}
{{- end }}
---
apiVersion: external-secrets.io/v1
kind: ExternalSecret
metadata: {name: ai-runtime, namespace: ai}
spec:
  refreshPolicy: Periodic
  refreshInterval: 1h
  secretStoreRef: {kind: SecretStore, name: aws-secretsmanager}
  target: {name: ai-runtime, creationPolicy: Orphan, deletionPolicy: Retain, template: {type: Opaque}}
  data:
  {{- range $key := concat $c.secretKeys $c.runnerExtraSecrets }}
    - secretKey: {{ $key }}
      remoteRef: {key: yeodam/v3/foundation/ai/runtime, property: {{ $key }}, version: AWSCURRENT, decodingStrategy: None}
  {{- end }}
  {{- if $.Values.langfuseEnabled }}
  {{- range $key := $obs.langfuseSecrets }}
    - secretKey: {{ $key }}
      remoteRef: {key: yeodam/v3/foundation/ai/runtime, property: {{ $key }}, version: AWSCURRENT, decodingStrategy: None}
  {{- end }}
  {{- end }}
{{- range $role, $w := $c.workloads }}
---
apiVersion: v1
kind: ServiceAccount
metadata: {name: {{ $w.name }}, namespace: ai}
automountServiceAccountToken: false
---
apiVersion: v1
kind: ConfigMap
metadata: {name: {{ $w.name }}-runtime, namespace: ai}
data:
  RELEASE: {{ $.Values.source | quote }}
  {{- if $.Values.traceContextEnabled }}
  JOBS_TRACE_CONTEXT_WRITE: {{ $.Values.traceContextWriteEnabled | toString | quote }}
  {{- end }}
  {{- if $.Values.langfuseEnabled }}
  {{- range $key, $value := $obs.langfuseEnvironment }}
  {{ $key }}: {{ $value | quote }}
  {{- end }}
  {{- end }}
  {{- range $key, $value := $c.commonEnvironment }}
  {{ $key }}: {{ $value | quote }}
  {{- end }}
  {{- if $.Values.tourapiEnabled }}
  {{- range $key, $value := $c.tourapiEnvironment }}
  {{ $key }}: {{ $value | quote }}
  {{- end }}
  {{- if eq $role "runner" }}
  {{- range $key, $value := $c.tourapiRunnerEnvironment }}
  {{ $key }}: {{ $value | quote }}
  {{- end }}
  {{- end }}
  {{- end }}
  {{- range $key, $value := $w.environment }}
  {{ $key }}: {{ $value | quote }}
  {{- end }}
{{- $apm := has $role $.Values.apmWorkloads }}
{{- $apmConfig := fromJson ($.Files.Get "files/apm.json") }}
{{- if index $.Values.workloads $role }}
---
apiVersion: apps/v1
kind: Deployment
metadata: {name: {{ $w.name }}, namespace: ai}
spec:
  replicas: 1
  revisionHistoryLimit: 2
  strategy: {type: Recreate}
  selector:
    matchLabels: {app.kubernetes.io/instance: {{ $w.name }}, yeodam.io/stage: v3}
  template:
    metadata:
      labels:
        app.kubernetes.io/name: ai
        app.kubernetes.io/instance: {{ $w.name }}
        app.kubernetes.io/component: {{ $role }}
        app.kubernetes.io/part-of: yeodam
        yeodam.io/stage: v3
        yeodam.io/ai-runtime: "true"
      annotations:
        checksum/runtime: {{ (printf "%s%s" ($.Files.Get "files/contract.json") (($.Files.Glob "files/runtime/*").AsConfig)) | sha256sum }}
        {{- if $.Values.traceContextEnabled }}
        checksum/observability: {{ printf "%s%t%t%t" ($.Files.Get "files/observability.json") $.Values.traceContextWriteEnabled $.Values.traceContextWriteEverEnabled $.Values.langfuseEnabled | sha256sum }}
        {{- end }}
        {{- if $apm }}
        checksum/apm: {{ printf "%s%s" ($.Files.Get "files/apm.json") ($.Files.Get "files/apm/sitecustomize.py") | sha256sum }}
        {{- end }}
        yeodam.io/configuration-revision: {{ $.Values.configurationRevision | quote }}
    spec:
      serviceAccountName: {{ $w.name }}
      automountServiceAccountToken: false
      imagePullSecrets: [{name: ghcr-pull}]
      nodeSelector: {yeodam.io/role: {{ $w.nodeRole }}, yeodam.io/stage: v3}
      tolerations: [{key: yeodam.io/role, operator: Equal, value: {{ $w.nodeRole }}, effect: NoSchedule}]
      terminationGracePeriodSeconds: {{ $w.grace }}
      securityContext:
        runAsNonRoot: true
        runAsUser: 10001
        runAsGroup: 10001
        fsGroup: 10001
        seccompProfile: {type: RuntimeDefault}
      initContainers:
        - name: prepare-trust
          image: {{ $.Values.image }}
          command: [python, /runtime/prepare-trust.py]
          resources: {requests: {cpu: 25m, memory: 32Mi}, limits: {memory: 64Mi}}
          securityContext: {allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: {drop: [ALL]}}
          volumeMounts:
            - {name: scripts, mountPath: /runtime, readOnly: true}
            - {name: public-ca, mountPath: /etc/yeodam/ca, readOnly: true}
            - {name: trust, mountPath: /etc/yeodam/trust}
        {{- if $apm }}
        - name: prepare-apm
          image: {{ $apmConfig.pythonImage }}
          command: [cp, -R, /autoinstrumentation/., /otel/]
          resources: {requests: {cpu: 25m, memory: 32Mi}, limits: {cpu: 100m, memory: 64Mi}}
          securityContext: {allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: {drop: [ALL]}}
          volumeMounts: [{name: apm, mountPath: /otel}]
        {{- end }}
      containers:
        - name: ai
          image: {{ $.Values.image }}
          command: {{ $w.command | toJson }}
          envFrom: [{configMapRef: {name: {{ $w.name }}-runtime}}]
          env:
          {{- $keys := $c.secretKeys }}
          {{- if eq $role "runner" }}{{ $keys = concat $keys $c.runnerExtraSecrets }}{{ end }}
          {{- range $key := $keys }}
            - name: {{ $key }}
              valueFrom: {secretKeyRef: {name: ai-runtime, key: {{ $key }}}}
          {{- end }}
          {{- if $.Values.langfuseEnabled }}
          {{- range $key := $obs.langfuseSecrets }}
            - {name: {{ $key }}, valueFrom: {secretKeyRef: {name: ai-runtime, key: {{ $key }}}}}
          {{- end }}
          {{- end }}
          {{- if $apm }}
            - {name: YEODAM_APM_ENABLED, value: 'true'}
            - {name: PYTHONPATH, value: '/runtime:/otel:/app'}
            - {name: OTEL_SERVICE_NAME, value: {{ $w.name | quote }}}
            - {name: OTEL_SERVICE_VERSION, value: {{ $.Values.source | quote }}}
            - {name: OTEL_EXPORTER_OTLP_ENDPOINT, value: {{ $apmConfig.endpoint | quote }}}
            - {name: OTEL_METRICS_EXPORTER, value: none}
            - {name: OTEL_LOGS_EXPORTER, value: none}
          {{- end }}
          resources:
{{ $w.resources | toYaml | indent 12 }}
          securityContext: {allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: {drop: [ALL]}}
          {{- if eq $role "api" }}
          ports: [{name: http, containerPort: 8000}]
          startupProbe: {httpGet: {path: /health, port: http}, periodSeconds: 5, timeoutSeconds: 5, failureThreshold: 60}
          readinessProbe: {httpGet: {path: /health, port: http}, periodSeconds: 10, timeoutSeconds: 5, failureThreshold: 3}
          livenessProbe: {exec: {command: [python, /runtime/health.py, api-live]}, periodSeconds: 20, timeoutSeconds: 5, failureThreshold: 3}
          {{- else }}
          startupProbe: {exec: {command: [python, /runtime/health.py, runner-ready]}, periodSeconds: 10, timeoutSeconds: 5, failureThreshold: 180}
          readinessProbe: {exec: {command: [python, /runtime/health.py, runner-ready]}, periodSeconds: 15, timeoutSeconds: 5, failureThreshold: 3}
          {{- end }}
          volumeMounts:
            - {name: scripts, mountPath: /runtime, readOnly: true}
            - {name: public-ca, mountPath: /etc/yeodam/ca, readOnly: true}
            - {name: trust, mountPath: /etc/yeodam/trust, readOnly: true}
            - {name: tmp, mountPath: /tmp}
            - {name: model-url, mountPath: /var/run/yeodam-vlm, readOnly: true}
            {{- if eq $role "runner" }}
            - {name: reference, mountPath: /data/ai-reference}
            {{- end }}
          {{- if $apm }}
            - {name: apm, mountPath: /otel, readOnly: true}
          {{- end }}
      volumes:
        {{- if $apm }}
        - {name: apm, emptyDir: {sizeLimit: 64Mi}}
        {{- end }}
        - {name: scripts, configMap: {name: ai-runtime-scripts, defaultMode: 0444}}
        - {name: public-ca, configMap: {name: ai-trust}}
        - {name: trust, emptyDir: {sizeLimit: 1Mi}}
        - {name: tmp, emptyDir: {sizeLimit: 256Mi}}
        - name: model-url
          secret:
            secretName: ai-runtime
            items: [{key: VLM_BASE_URL, path: base-url}]
        {{- if eq $role "runner" }}
        - {name: reference, emptyDir: {sizeLimit: 3Gi}}
        {{- end }}
{{- end }}
{{- end }}
{{- if .Values.workloads.api }}
---
apiVersion: v1
kind: Service
metadata: {name: ai-api, namespace: ai}
spec:
  type: ClusterIP
  selector: {app.kubernetes.io/instance: ai-api, yeodam.io/stage: v3}
  ports: [{name: http, port: 8000, targetPort: http}]
{{- end }}
{{- range $p := .Files.Get "files/policies.json" | fromJsonArray }}
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata: {name: {{ $p.name }}, namespace: {{ $p.namespace }}}
spec:
{{ $p.spec | toYaml | indent 2 }}
{{- end }}
{{- if .Values.privateModelPeers }}
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata: {name: allow-ai-reviewed-private-models, namespace: ai}
spec:
  podSelector:
    matchLabels: {yeodam.io/ai-runtime: "true", yeodam.io/stage: v3}
  policyTypes: [Egress]
  egress:
  {{- range $peer := .Values.privateModelPeers }}
    - to: [{ipBlock: {cidr: {{ $peer.cidr | quote }}}}]
      ports: [{protocol: TCP, port: {{ $peer.port }}}]
  {{- end }}
{{- end }}
{{- end }}

values.schema.json:
{
  "$schema": "https://json-schema.org/draft-07/schema#",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "accessEnabled",
    "workloads",
    "image",
    "source",
    "configurationRevision",
    "review",
    "trust",
    "privateModelPeers"
  ],
  "properties": {
    "apmWorkloads": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "enum": [
          "api",
          "runner"
        ]
      }
    },
    "accessEnabled": {
      "type": "boolean"
    },
    "workloads": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "api",
        "runner"
      ],
      "properties": {
        "api": {
          "type": "boolean"
        },
        "runner": {
          "type": "boolean"
        }
      }
    },
    "image": {
      "type": "string"
    },
    "source": {
      "type": "string"
    },
    "configurationRevision": {
      "type": "string"
    },
    "review": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "sourceCompatible",
        "imageReviewed",
        "connectionsReviewed"
      ],
      "properties": {
        "sourceCompatible": {
          "type": "boolean"
        },
        "imageReviewed": {
          "type": "boolean"
        },
        "connectionsReviewed": {
          "type": "boolean"
        }
      }
    },
    "trust": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "redis",
        "qdrant",
        "kafka"
      ],
      "properties": {
        "redis": {
          "type": "string"
        },
        "qdrant": {
          "type": "string"
        },
        "kafka": {
          "type": "string"
        }
      }
    },
    "privateModelPeers": {
      "type": "array",
      "maxItems": 2,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "cidr",
          "port"
        ],
        "properties": {
          "cidr": {
            "type": "string",
            "pattern": "^10\\.[0-9]+\\.[0-9]+\\.[0-9]+/32$"
          },
          "port": {
            "type": "integer",
            "minimum": 1,
            "maximum": 65535
          }
        }
      }
    },
    "tourapiEnabled": {
      "type": "boolean"
    },
    "traceContextEnabled": {
      "type": "boolean"
    },
    "traceContextWriteEnabled": {
      "type": "boolean"
    },
    "traceContextWriteEverEnabled": {
      "type": "boolean"
    },
    "langfuseEnabled": {
      "type": "boolean"
    }
  }
}
